import{_ as t,o as s,c as o,l as r,t as i,N as n}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"git-restore | x-cmd man (git man1) | Restore working tree files","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-restore - Restore working tree files","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-restore | x-cmd man (git man1) | Restore working tree files"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-restore - Restore working tree files"}]]},"headers":[],"params":{"isMan":true,"man":"git-restore","category":"git man1","desc":"Restore working tree files"},"relativePath":"git/man1/git-restore.md","filePath":"git/man1/git-restore.md"}'),a={name:"git/man1/git-restore.md"},l={class:"visually-hidden"},h=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-restore - Restore working tree files</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] [--source</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tree</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--staged] [--worktree] [--] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pathspec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] [--source</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tree</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--staged] [--worktree] --pathspec-from-file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> [--pathspec-file-nul]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (-p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--patch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--source</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tree</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--staged] [--worktree] [--] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pathspec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Restore specified paths in the working tree with some contents from a restore source. If a path is tracked but does not exist in the restore source, it will be removed to match the source.</p><p>The command can also be used to restore the content in the index with <strong>--staged</strong>, or restore both the working tree and the index with <strong>--staged --worktree</strong>.</p><p>By default, if <strong>--staged</strong> is given, the contents are restored from <strong>HEAD</strong>, otherwise from the index. Use <strong>--source</strong> to restore from a different commit.</p><p>See &quot;Reset, restore and revert&quot; in <strong>git</strong>(1) for the differences between the three commands.</p><p>THIS COMMAND IS EXPERIMENTAL. THE BEHAVIOR MAY CHANGE.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-s &lt;tree&gt;, --source=&lt;tree&gt;</p><blockquote><p>Restore the working tree files with the content from the given tree. It is common to specify the source tree by naming a commit, branch or tag associated with it.</p><p>If not specified, the contents are restored from <strong>HEAD</strong> if <strong>--staged</strong> is given, otherwise from the index.</p><p>As a special case, you may use <strong>&quot;A...B&quot;</strong> as a shortcut for the merge base of <strong>A</strong> and <strong>B</strong> if there is exactly one merge base. You can leave out at most one of <strong>A</strong> and <strong>B</strong>, in which case it defaults to <strong>HEAD</strong>.</p></blockquote><p>-p, --patch</p><blockquote><p>Interactively select hunks in the difference between the restore source and the restore location. See the &quot;Interactive Mode&quot; section of <strong>git-add</strong>(1) to learn how to operate the <strong>--patch</strong> mode.</p><p>Note that <strong>--patch</strong> can accept no pathspec and will prompt to restore all modified paths.</p></blockquote><p>-W, --worktree, -S, --staged</p><blockquote><p>Specify the restore location. If neither option is specified, by default the working tree is restored. Specifying <strong>--staged</strong> will only restore the index. Specifying both restores both.</p></blockquote><p>-q, --quiet</p><blockquote><p>Quiet, suppress feedback messages. Implies <strong>--no-progress</strong>.</p></blockquote><p>--progress, --no-progress</p><blockquote><p>Progress status is reported on the standard error stream by default when it is attached to a terminal, unless <strong>--quiet</strong> is specified. This flag enables progress reporting even if not attached to a terminal, regardless of <strong>--quiet</strong>.</p></blockquote><p>--ours, --theirs</p><blockquote><p>When restoring files in the working tree from the index, use stage #2 (<em>ours</em>) or #3 (<em>theirs</em>) for unmerged paths.</p><p>Note that during <strong>git rebase</strong> and <strong>git pull --rebase</strong>, <em>ours</em> and <em>theirs</em> may appear swapped. See the explanation of the same options in <strong>git-checkout</strong>(1) for details.</p></blockquote><p>-m, --merge</p><blockquote><p>When restoring files on the working tree from the index, recreate the conflicted merge in the unmerged paths.</p></blockquote><p>--conflict=&lt;style&gt;</p><blockquote><p>The same as <strong>--merge</strong> option above, but changes the way the conflicting hunks are presented, overriding the <strong>merge.conflictStyle</strong> configuration variable. Possible values are &quot;merge&quot; (default), &quot;diff3&quot;, and &quot;zdiff3&quot;.</p></blockquote><p>--ignore-unmerged</p><blockquote><p>When restoring files on the working tree from the index, do not abort the operation if there are unmerged entries and neither <strong>--ours</strong>, <strong>--theirs</strong>, <strong>--merge</strong> or <strong>--conflict</strong> is specified. Unmerged paths on the working tree are left alone.</p></blockquote><p>--ignore-skip-worktree-bits</p><blockquote><p>In sparse checkout mode, by default is to only update entries matched by <strong>&lt;pathspec&gt;</strong> and sparse patterns in $GIT_DIR/info/sparse-checkout. This option ignores the sparse patterns and unconditionally restores any files in <strong>&lt;pathspec&gt;</strong>.</p></blockquote><p>--recurse-submodules, --no-recurse-submodules</p><blockquote><p>If <strong>&lt;pathspec&gt;</strong> names an active submodule and the restore location includes the working tree, the submodule will only be updated if this option is given, in which case its working tree will be restored to the commit recorded in the superproject, and any local modifications overwritten. If nothing (or <strong>--no-recurse-submodules</strong>) is used, submodules working trees will not be updated. Just like <strong>git-checkout</strong>(1), this will detach <strong>HEAD</strong> of the submodule.</p></blockquote><p>--overlay, --no-overlay</p><blockquote><p>In overlay mode, the command never removes files when restoring. In no-overlay mode, tracked files that do not appear in the <strong>--source</strong> tree are removed, to make them match <strong>&lt;tree&gt;</strong> exactly. The default is no-overlay mode.</p></blockquote><p>--pathspec-from-file=&lt;file&gt;</p><blockquote><p>Pathspec is passed in <strong>&lt;file&gt;</strong> instead of commandline args. If <strong>&lt;file&gt;</strong> is exactly <strong>-</strong> then standard input is used. Pathspec elements are separated by LF or CR/LF. Pathspec elements can be quoted as explained for the configuration variable <strong>core.quotePath</strong> (see <strong>git-config</strong>(1)). See also <strong>--pathspec-file-nul</strong> and global <strong>--literal-pathspecs</strong>.</p></blockquote><p>--pathspec-file-nul</p><blockquote><p>Only meaningful with <strong>--pathspec-from-file</strong>. Pathspec elements are separated with NUL character and all other characters are taken literally (including newlines and quotes).</p></blockquote><p>--</p><blockquote><p>Do not interpret any more arguments as options.</p></blockquote><p>&lt;pathspec&gt;...</p><blockquote><p>Limits the paths affected by the operation.</p><p>For more details, see the <em>pathspec</em> entry in <strong>gitglossary</strong>(7).</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>The following sequence switches to the <strong>master</strong> branch, reverts the <strong>Makefile</strong> to two revisions back, deletes hello.c by mistake, and gets it back from the index.</p><blockquote><pre><code>$ git switch master
$ git restore --source master~2 Makefile  (1)
$ rm -f hello.c
$ git restore hello.c                     (2)
</code></pre></blockquote><hr><pre><code>**1.** take a file out of another commit
**2.** restore hello.c from the index
</code></pre><hr><p>If you want to restore <em>all</em> C source files to match the version in the index, you can say</p><blockquote><pre><code>$ git restore &#39;*.c&#39;
</code></pre></blockquote><p>Note the quotes around <strong>*.c</strong>. The file <strong>hello.c</strong> will also be restored, even though it is no longer in the working tree, because the file globbing is used to match entries in the index (not in the working tree by the shell).</p><p>To restore all files in the current directory</p><blockquote><pre><code>$ git restore .
</code></pre></blockquote><p>or to restore all working tree files with <em>top</em> pathspec magic (see <strong>gitglossary</strong>(7))</p><blockquote><pre><code>$ git restore :/
</code></pre></blockquote><p>To restore a file in the index to match the version in <strong>HEAD</strong> (this is the same as using <strong>git-reset</strong>(1))</p><blockquote><pre><code>$ git restore --staged hello.c
</code></pre></blockquote><p>or you can restore both the index and the working tree (this the same as using <strong>git-checkout</strong>(1))</p><blockquote><pre><code>$ git restore --source=HEAD --staged --worktree hello.c
</code></pre></blockquote><p>or the short form which is more practical but less readable:</p><blockquote><pre><code>$ git restore -s@ -SW hello.c
</code></pre></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-checkout</strong>(1), <strong>git-reset</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,66);function p(e,g,c,d,k,u){return s(),o("div",null,[r("h1",l,i(e.$params.man),1),h])}const b=t(a,[["render",p]]);export{f as __pageData,b as default};
